package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Color;
import org.bukkit.Particle;
import org.bukkit.entity.Enderman;
import org.bukkit.entity.Player;
import org.bukkit.event.entity.EntityTeleportEvent;
import org.bukkit.potion.PotionType;

public final class ToxicEndermanBehaviour implements CompiledBehaviour {
    private static final Particle DRAGON_BREATH = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dragon_breath");

    private static final PotionType STRONG_POISON = Registries.entry(RegistryKey.POTION, "minecraft:strong_poison");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle DUST = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dust");

    private final MobContext context;

    private Cooldown cooldown;

    public ToxicEndermanBehaviour(MobContext context) {
        this.context = context;
        // node #29 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onNightEnd() {
        // node #7 mob.night_end
        // node #9 world.spawn_particle
        // node #8 mob.self
        final Enderman self = ((Enderman) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), DRAGON_BREATH, self.getEyeLocation(), 10, 1.5d, 1.0d, 1.5d, Float.valueOf((float) 1.0d));
        // node #10
    }

    @Override
    public void onTeleport(EntityTeleportEvent event) {
        // node #16 event.teleport
        // node #17 world.spawn_potion_cloud
        BukkitRuntime.potionCloud(this.context, event.getFrom(), STRONG_POISON, 10, 4.0d, 0.01d, Color.fromRGB(0, 128, 0));
        // node #18
    }

    @Override
    public void onTick() {
        // node #38 mob.tick
        // node #43 flow.branch
        // node #39 mob.self
        final Enderman self = ((Enderman) this.context.entity());
        if (self.getTarget() == null) {
            // node #42 flow.branch
            // node #40 world.nearest_player
            final Player player = BukkitRuntime.nearestPlayer(self.getLocation(), 16.0d, true);
            if (player != null) {
                // node #41 mob.mutate
                self.setTarget(player);
            }
        }
        // node #46 flow.branch
        // node #44 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (!cooldown) return;
        // node #45 world.spawn_particle
        BukkitRuntime.particles(this.context, self.getWorld(), DUST, self.getEyeLocation(), 5, 1.5d, 1.0d, 1.5d, new Particle.DustOptions(Color.fromRGB(0, 128, 0), 2.0f));
        // node #47
    }
}
